import { Controller } from '@nestjs/common';

// 이 기능은 화면만 만든다.
// POST /expense-resolutions, POST /expense-resolutions/:expenseResolutionId/submit 은 다른 기능이 만든다.
@Controller('api/v1')
export class FnSfr03212Controller {}

