import { useState } from 'react';
import {
  call,
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  RefName,
  Select,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

const EVIDENCE_TYPES: [string, string][] = [
  ['통장', '통장'],
  ['카드', '카드'],
  ['현금영수증', '현금영수증'],
  ['전자세금계산서', '전자세금계산서'],
];

export default function FnSfr03212Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 작성한 결의서를 목록으로 보인다.
  const [rows, setRows] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [resolutionDate, setResolutionDate] = useState('');
  const [purchaseRequestId, setPurchaseRequestId] = useState<unknown>('');
  const [projectId, setProjectId] = useState<unknown>('');
  const [budgetItemId, setBudgetItemId] = useState<unknown>('');
  const [amount, setAmount] = useState<unknown>('');
  const [evidenceType, setEvidenceType] = useState('');
  const [partnerId, setPartnerId] = useState<unknown>('');
  const [departmentId, setDepartmentId] = useState<unknown>('');

  const reset = () => {
    setResolutionDate('');
    setPurchaseRequestId('');
    setProjectId('');
    setBudgetItemId('');
    setAmount('');
    setEvidenceType('');
    setPartnerId('');
    setDepartmentId('');
  };

  const empty = (v: unknown) => v === '' || v === null || v === undefined;

  const create = async () => {
    if (!resolutionDate) throw new Error('결의일자를 입력하세요.');
    if (empty(projectId)) throw new Error('프로젝트를 선택하세요.');
    if (empty(budgetItemId)) throw new Error('예산과목을 선택하세요.');
    if (empty(amount) || typeof amount !== 'number' || !(amount > 0)) {
      throw new Error('결의 금액은 0보다 큰 숫자로 입력하세요.');
    }
    if (!evidenceType) throw new Error('증빙 유형을 선택하세요.');
    if (empty(departmentId)) throw new Error('결의부서를 선택하세요.');
    const body: Row = {
      resolutionDate,
      projectId,
      budgetItemId,
      amount,
      evidenceType,
      departmentId,
    };
    if (!empty(purchaseRequestId)) body.purchaseRequestId = purchaseRequestId;
    if (!empty(partnerId)) body.partnerId = partnerId;
    const res = await call('POST', '/expense-resolutions', role, body);
    setRows([{ ...body, ...res }, ...rows]);
    notify('결의서를 저장했습니다.');
    reset();
    setOpen(false);
  };

  const submit = async (row: Row) => {
    try {
      const res = await call('POST', `/expense-resolutions/${row.expenseResolutionId}/submit`, role, {});
      setRows(rows.map((r) => (r.expenseResolutionId === row.expenseResolutionId ? { ...r, approvalStatus: res.approvalStatus } : r)));
      notify('결재를 상신했습니다.');
    } catch (e) {
      notify(e instanceof Error ? e.message : '상신에 실패했습니다.');
    }
  };

  const total = rows.reduce((sum, r) => sum + (typeof r.amount === 'number' ? r.amount : 0), 0);
  const drafts = rows.filter((r) => r.approvalStatus === '기안').length;

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>작성 현황</h2>
        <Tiles
          items={[
            ['작성 건수', <Num value={rows.length} />],
            ['상신 대기', <Num value={drafts} />],
            ['결의 금액 합계', <Num value={total} />],
          ]}
        />
      </section>
      <section className='box span-12'>
        <h2>결의서 목록</h2>
        <Band total={rows.length}>
          <button type='button' onClick={() => setOpen(true)}>결의서 작성</button>
        </Band>
        <DataTable
          rows={rows}
          empty='작성한 결의서가 없습니다.'
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'resolutionDate', label: '결의일자', render: (r) => <DateText value={r.resolutionDate} /> },
            { key: 'departmentId', label: '결의부서', render: (r) => <RefName table='department' role={role} value={r.departmentId} /> },
            { key: 'projectId', label: '프로젝트', render: (r) => <RefName table='project' role={role} value={r.projectId} /> },
            { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table='budget_item' role={role} value={r.budgetItemId} /> },
            { key: 'amount', label: '결의 금액', render: (r) => <Num value={r.amount} /> },
            { key: 'evidenceType', label: '증빙 유형' },
            { key: 'approvalStatus', label: '결재 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.approvalStatus === '기안' ? (
                  <button type='button' onClick={() => submit(r)}>결재 상신</button>
                ) : null,
            },
          ]}
        />
      </section>
      {open && (
        <Drawer title='결의서 작성' onClose={() => setOpen(false)}>
          <Form onSubmit={create} submit='저장'>
            <Field label='결의일자' required>
              <DateInput value={resolutionDate} onChange={setResolutionDate} />
            </Field>
            <Field label='결의부서' required>
              <LookupSelect table='department' role={role} value={departmentId} onChange={setDepartmentId} />
            </Field>
            <Field label='프로젝트' required>
              <LookupSelect table='project' role={role} value={projectId} onChange={setProjectId} />
            </Field>
            <Field label='예산과목' required>
              <LookupSelect table='budget_item' role={role} value={budgetItemId} onChange={setBudgetItemId} />
            </Field>
            <Field label='결의 금액' required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label='증빙 유형' required>
              <Select value={evidenceType} onChange={setEvidenceType} options={EVIDENCE_TYPES} />
            </Field>
            <Field label='거래처'>
              <LookupSelect table='partner' role={role} value={partnerId} onChange={setPartnerId} />
            </Field>
            <Field label='연결 품의서'>
              <LookupSelect table='purchase_request' role={role} value={purchaseRequestId} onChange={setPurchaseRequestId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
